CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans(dim integer, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit integer) RETURNS TABLE(moved bigint, sample jsonb) LANGUAGE plpgsql AS $function$ DECLARE v_p35b_con text; -- the constraint of a unique_violation, for the retry on the id twin v_moved bigint; v_sample jsonb; v_collision_count bigint; v_collision_sample text[]; v_sample_limit int; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; v_origin_id bigint; v_quarantine_id bigint; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_quarantine_orphans: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- nexus-0uuit/sybbh crit-fix critique 2026-08-19 (code-review-expert): -- p_sample_limit is caller-supplied over HTTP (VectorHandler's -- handleGcQuarantineOrphans, optInt default 20) and unlike purge_trash / -- gc_expire_quarantine (both hard-capped in-function), this function -- previously trusted it unbounded -- a caller passing a large -- sample_limit could insert a gc_audit row with an unbounded chashes -- array. VectorHandler now clamps server-side too, but this is defense -- in depth: the SAME GC_AUDIT_MAX_CHASHES cap (5000, CatalogRepository. -- java) enforced here independently of the HTTP layer. Carried forward -- from catalog-033-2 into this changeset's body (nexus-uxd2a; see this -- changeset's own comment above). v_sample_limit := LEAST(GREATEST(COALESCE(p_sample_limit, 20), 0), 5000);
-- nexus-sa731: EXCLUSIVE half of the RDR-191 sweep gate (unchanged from -- catalog-028-1 — see that changeset's comment for the full derivation). PERFORM set_config('lock_timeout', '2000', true); PERFORM set_config('statement_timeout', '5000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'gc_quarantine_orphans: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer is holding it; retry', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
-- RDR-192 Step 8 (nexus-wbfpw.16): the candidate set is reapable(c), nexus.chunk_is_reapable -- (vectors-021): no own-collection manifest row in any owner state, last_written_at past the -- grace (default 30 days), not a quarantine sibling. It is chosen ONCE here and every later -- statement reads this one set, so a condition that lapses between the copy INSERT and the -- DELETE cannot delete a chunk that was not copied. The DELETE re-checks the predicate on its -- target row, so a client write that refreshes last_written_at after this point wins at the -- READ COMMITTED recheck and the chunk stays. -- RDR-229 P3.5b: the origin's registry id, resolved once from the label the caller passes (label-kept registry read). -- A chunk row is the origin's when it carries that id, or carries none and names the label. SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_collection;
CREATE TEMP TABLE IF NOT EXISTS _wbfpw16_victim(chash bytea PRIMARY KEY) ON COMMIT DROP; DELETE FROM _wbfpw16_victim; INSERT INTO _wbfpw16_victim(chash) SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( p_tenant_id, p_collection, c.chash, c.last_written_at, NULL));
IF NOT EXISTS (SELECT 1 FROM _wbfpw16_victim) THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb; RETURN; END IF;
-- N7-STYLE cross-dim collision guard (Critical-1 fix, T2 [22454]): the -- unified PK (tenant_id, collection, chash) cannot hold two different- -- dim rows. Detect, BEFORE any row moves, any orphan whose chash -- already exists at p_quarantine_collection under a DIFFERENT -- populated embedding_<dim> column than the orphan's own -- the blind -- ON CONFLICT ... DO UPDATE ... EXCLUDED below would otherwise -- silently overwrite (destroy) one of the two chunks' text/embedding. -- RAISE aborts only THIS (tenant, collection) sweep call -- an ongoing -- GC cycle, not vectors-004's one-time migration, so the bounded -- blast radius is one collection's pass, retried next cycle, not the -- whole batch. SELECT cc.collection_id INTO v_quarantine_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection;
WITH orphan AS ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim FROM nexus.chunks c JOIN _wbfpw16_victim v ON v.chash = c.chash WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) ), collision AS ( SELECT o.chash, o.src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM orphan o JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND (e.collection_id = v_quarantine_id OR (e.collection_id IS NULL AND e.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND e.chash = o.chash ) SELECT count(*), COALESCE(array_agg(encode(chash, 'hex') ORDER BY chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM collision WHERE src_dim IS DISTINCT FROM existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans: % cross-dim (tenant_id, collection, chash) collision(s) at quarantine target % for tenant=%, origin collection=% -- the unified PK cannot hold two different-dim rows for the same chash (mirrors vectors-004''s N7 guard, T2 22454). Sample chashes: %. Refusing to overwrite; verify the quarantine-collection naming keeps distinct dims/collections separated before retrying.', v_collision_count, p_quarantine_collection, p_tenant_id, p_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- Registration MUST precede the copy INSERT below (FK on collection). -- RDR-204 nexus-uxd2a (hygiene-005-1): NO ENGINE PATH DERIVES A -- COLLECTION'S ATTRIBUTES FROM ITS NAME (coordinator nexus-71 -- decision -- see this changelog file's own header). The PRIOR body -- (hygiene-002-2) parsed p_quarantine_collection's OWN name via -- string_to_array(name, '__') -- for the real production shape -- "quarantine-<ct>__owner__model__vN" that split v_seg[1] to the -- LITERAL FIRST SEGMENT, "quarantine-<ct>" WITH THE PREFIX STILL -- ATTACHED (the migration-time walk's regex-based branch B, by -- contrast, has always captured the base type via a capture group that -- excludes the prefix) -- shipped as a live defect (nexus-uxd2a: a real -- row landed with content_type = 'quarantine-code', outside the CCE -- profile vocabulary). p_collection (the ORIGIN) is ALWAYS already -- registered by this point -- every caller resolves dim from it before -- ever reaching this function (PgVectorRepository.quarantineOrphans) -- -- so its own row is the one true source for the quarantine sibling's -- attributes. An unregistered origin is now a fail-loud precondition, -- never a silent 'unknown' stub. SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'gc_quarantine_orphans: origin collection % is not registered for tenant % -- attributes for the quarantine sibling are copied from the origin row, never parsed from the quarantine sibling name (RDR-204 nexus-uxd2a); register the origin before quarantining orphans', p_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections AS cc0 (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_quarantine_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'quarantine' ) ON CONFLICT (tenant_id, name) WHERE superseded_by = '' AND superseded_by_id IS NULL DO UPDATE SET content_type = EXCLUDED.content_type, owner_id = EXCLUDED.owner_id, embedding_model = EXCLUDED.embedding_model, model_version = EXCLUDED.model_version, dimension = EXCLUDED.dimension, superseded_by_id = CASE WHEN cc0.superseded_by = '' THEN NULL ELSE COALESCE(cc0.superseded_by_id, (SELECT s.collection_id FROM nexus.catalog_collections s WHERE s.tenant_id = cc0.tenant_id AND s.name = cc0.superseded_by), cc0.collection_id) END WHERE cc0.lifecycle_state = 'quarantine' OR NOT EXISTS (SELECT 1 FROM nexus.catalog_collections h WHERE h.tenant_id = cc0.tenant_id AND h.collection_id <> cc0.collection_id AND h.superseded_by = '' AND h.lifecycle_state <> 'quarantine' AND h.content_type = EXCLUDED.content_type AND h.owner_id = EXCLUDED.owner_id AND h.embedding_model = EXCLUDED.embedding_model AND h.model_version = EXCLUDED.model_version);
-- nexus-p2m1x.28 (linda 2026-11-25): the refresh above copies the ORIGIN's tuple onto a row that bears the sibling's name. For a quarantine row -- that is the designed heal and the row is outside catalog_collections_live_tuple_uq. A row of any other lifecycle that bears the name -- is inside the index, so the copy is skipped by the WHERE when another live row (the origin, as a rule) already holds that tuple, and -- the call refuses here by name: nothing moved, no second live holder, never a bare 23505. A non-quarantine row with no live twin of the tuple is refreshed as before. IF NOT FOUND THEN RAISE EXCEPTION 'gc_quarantine_orphans: the row named % is not a quarantine collection and another live collection already holds the tuple of origin % that the quarantine sibling would copy onto it; nothing moved (the live tuple index allows one live holder of a tuple)', p_quarantine_collection, p_collection USING ERRCODE = 'invalid_parameter_value'; END IF;
-- two unique keys on nexus.chunks until P4.1 (the name primary key and P3.3b's id twin on (tenant_id, collection_id, chash, embedding_model)): the ON CONFLICT -- arbiter absorbs a race on itself only, so a racing writer's row trips the twin as a plain 23505. Retry once when the -- 23505 is that twin (a unique index whose partition root is nexus.chunks, on the id key's columns); the retry sees the committed row on the arbiter. Any other 23505, or a second one, is raised (linda 2026-11-22). FOR v_p35b_try IN 1 .. 2 LOOP BEGIN -- RDR-225: the row carries its own embedding_model (the quarantine sibling is registered under the -- origin's model just above, so the model is the same and the composite collection foreign key holds), -- and the arbiter is the four-column primary key of the partitioned table. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, embedding_model, collection_id) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) || jsonb_strip_nulls(jsonb_build_object('origin_collection_id', (SELECT oc.collection_id FROM nexus.catalog_collections oc WHERE oc.tenant_id = p_tenant_id AND oc.name = p_collection))), c.embedding_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection) FROM nexus.chunks c JOIN _wbfpw16_victim v ON v.chash = c.chash WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) ON CONFLICT (tenant_id, collection, chash, embedding_model) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding_384 = EXCLUDED.embedding_384, embedding_768 = EXCLUDED.embedding_768, embedding_1024 = EXCLUDED.embedding_1024, metadata = EXCLUDED.metadata, collection_id = EXCLUDED.collection_id; EXIT; EXCEPTION WHEN unique_violation THEN GET STACKED DIAGNOSTICS v_p35b_con = CONSTRAINT_NAME; IF v_p35b_try = 2 OR NOT EXISTS ( SELECT 1 FROM pg_catalog.pg_class ic JOIN pg_catalog.pg_namespace ns ON ns.oid = ic.relnamespace JOIN pg_catalog.pg_index ix ON ix.indexrelid = ic.oid WHERE ns.nspname = 'nexus' AND ic.relname = v_p35b_con AND ix.indisunique AND coalesce(pg_catalog.pg_partition_root(ix.indrelid), ix.indrelid) = 'nexus.chunks'::regclass AND (SELECT pg_catalog.array_agg(a.attname::text ORDER BY a.attname) FROM pg_catalog.pg_attribute a WHERE a.attrelid = ix.indrelid AND a.attnum = ANY (ix.indkey)) = ARRAY['chash', 'collection_id', 'embedding_model', 'tenant_id']) THEN RAISE; END IF; END; END LOOP;
WITH del AS ( DELETE FROM nexus.chunks c USING _wbfpw16_victim v WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) AND c.chash = v.chash AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( p_tenant_id, p_collection, c.chash, c.last_written_at, NULL)) RETURNING c.tenant_id, c.collection, c.collection_id, c.chash, c.embedding_model, left(c.chunk_text, 80) AS text_prefix ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(lim.chash, 'hex'), 'title', lim.title, 'text_prefix', lim.text_prefix)) AS s FROM (SELECT d.chash, d.text_prefix, (SELECT od.title FROM nexus.catalog_document_chunks oc JOIN nexus.catalog_documents od ON od.tenant_id = oc.tenant_id AND od.tumbler = oc.doc_id WHERE oc.tenant_id = d.tenant_id AND oc.chash = d.chash AND oc.embedding_model = d.embedding_model AND od.deleted_at IS NULL ORDER BY COALESCE((oc.collection_id = d.collection_id OR ((oc.collection_id IS NULL OR d.collection_id IS NULL) AND oc.collection = d.collection AND oc.collection <> '')), false) DESC, oc.doc_id LIMIT 1) AS title FROM del d LIMIT v_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
-- nexus-sybbh: audit the move IN THE SAME TRANSACTION as the DELETE -- above. `chashes` here is deliberately the v_sample_limit-capped -- sample the function already computes (extracting just the chash -- field) -- chash_count still carries the exact full v_moved count -- regardless of sample size. `chashes_truncated`/`chashes_stored` are -- set (same convention as purge_trash / gc_expire_quarantine) only -- when the CALLER's requested p_sample_limit itself exceeded -- GC_AUDIT_MAX_CHASHES and had to be clamped -- distinct from -- `chashes_is_sample`, which is always true here by design (the sample -- is intentionally partial even when p_sample_limit is well within -- bounds). Carried forward from catalog-033-2 into this changeset's -- body (nexus-uxd2a; catalog-033-2's original comment, adapted). INSERT INTO nexus.gc_audit (tenant_id, operation, collection, collection_id, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_quarantine_orphans', p_collection, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_collection), 'engine', false, v_moved, COALESCE( (SELECT jsonb_agg(elem->>'chash') FROM jsonb_array_elements(COALESCE(v_sample, '[]'::jsonb)) elem), '[]'::jsonb), jsonb_build_object( 'quarantine_collection', p_quarantine_collection, 'sample_limit', v_sample_limit, 'chashes_is_sample', true) || CASE WHEN COALESCE(p_sample_limit, 20) > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END );
RETURN QUERY SELECT v_moved, v_sample; END; $function$;

