IF NOT FOUND THEN RAISE EXCEPTION 'gc_quarantine_orphans: origin collection % is not registered for tenant % -- attributes for the quarantine sibling are copied from the origin row, never parsed from the quarantine sibling name (RDR-204 nexus-uxd2a); register the origin before quarantining orphans', p_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections AS cc0 (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_quarantine_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'quarantine' ) ON CONFLICT (tenant_id, name) WHERE superseded_by = '' AND superseded_by_id IS NULL DO UPDATE SET content_type = EXCLUDED.content_type, owner_id = EXCLUDED.owner_id, embedding_model = EXCLUDED.embedding_model, model_version = EXCLUDED.model_version, dimension = EXCLUDED.dimension, superseded_by_id = CASE WHEN cc0.superseded_by = '' THEN NULL ELSE COALESCE(cc0.superseded_by_id, (SELECT s.collection_id FROM nexus.catalog_collections s WHERE s.tenant_id = cc0.tenant_id AND s.name = cc0.superseded_by), cc0.collection_id) END;
