CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans_bounded(dim integer, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit integer, p_row_limit integer) RETURNS TABLE(moved bigint, sample jsonb, remaining bigint) LANGUAGE plpgsql AS $function$ DECLARE v_p35b_con text; -- the constraint of a unique_violation, for the retry on the id twin v_origin_id bigint; v_quar_id bigint; v_moved bigint; v_sample jsonb; v_remaining bigint; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; v_collision_count bigint; v_collision_sample text[]; v_sample_limit int; v_row_limit int; BEGIN SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_collection; SELECT cc.collection_id INTO v_quar_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection; IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- A non-positive bound is a caller error, not "unbounded". The whole point -- of this function is the bound; silently removing it would hand back the -- 58-second transaction this exists to prevent. IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: p_row_limit must be positive, got %. Use nexus.gc_quarantine_orphans for the unbounded sweep.', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
v_sample_limit := LEAST(GREATEST(COALESCE(p_sample_limit, 20), 0), 5000); v_row_limit := LEAST(p_row_limit, 100000);
PERFORM set_config('lock_timeout', '2000', true); PERFORM set_config('statement_timeout', '25000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN -- nexus-a6mon requirement 4: name the caller's OWN in-flight call as -- a possibility. The unbounded form advised "retry", which cannot -- succeed while the holder IS the caller's previous, still-committing -- call -- the exact state a cut-then-resubmit loop produces. RAISE EXCEPTION 'gc_quarantine_orphans_bounded: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer holds it, OR your own previous bounded call is still committing after the edge cut you. Poll pg_stat_activity for an active sweep on this collection before retrying; a fixed sleep builds a lock convoy.', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
-- THE VICTIM SET, chosen ONCE and ordered for deterministic progress. -- RDR-192 Step 8 (nexus-wbfpw.16): a candidate is reapable(c), nexus.chunk_is_reapable -- (vectors-021): no own-collection manifest row in any owner state, last_written_at past -- the grace (default 30 days), not a quarantine sibling. The DELETE below re-checks it on -- the target row, so a refresh that lands after the victim set was chosen wins at the -- READ COMMITTED recheck and the chunk stays. CREATE TEMP TABLE IF NOT EXISTS _a6mon_victim(chash bytea PRIMARY KEY) ON COMMIT DROP; DELETE FROM _a6mon_victim; INSERT INTO _a6mon_victim(chash) SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( p_tenant_id, p_collection, c.chash, c.last_written_at, NULL)) ORDER BY c.chash LIMIT v_row_limit;
IF NOT EXISTS (SELECT 1 FROM _a6mon_victim) THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb, 0::bigint; RETURN; END IF;
-- Cross-dim collision guard, same contract as the unbounded form -- (vectors-004's N7 guard, T2 22454) but scoped to this batch. SELECT count(*), COALESCE(array_agg(encode(x.chash, 'hex') ORDER BY x.chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM nexus.chunks c JOIN _a6mon_victim v ON v.chash = c.chash JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND (e.collection_id = v_quar_id OR (e.collection_id IS NULL AND e.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND e.chash = c.chash WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) ) x WHERE x.src_dim IS DISTINCT FROM x.existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: % cross-dim (tenant_id, collection, chash) collision(s) at quarantine target % for tenant=%, origin collection=%. Sample chashes: %. Refusing to overwrite.', v_collision_count, p_quarantine_collection, p_tenant_id, p_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- nexus-0rxvg: the quarantine sibling's attributes are copied from the -- ORIGIN's registered row, never parsed from the sibling's own name. The -- catalog-037-1 body split p_quarantine_collection on '__', so for the -- production shape quarantine-<ct>__owner__model__vN the first segment -- carried the prefix and the sibling registered with content_type -- 'quarantine-<ct>' and no dimension -- the defect hygiene-005-1 retired -- in the unbounded twin. PgVectorRepository.quarantineOrphansBounded -- resolves dim from the origin before reaching this function, so an -- unregistered origin is a fail-loud precondition here, as there. SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: origin collection % is not registered for tenant % -- attributes for the quarantine sibling are copied from the origin row, never parsed from the quarantine sibling name (nexus-0rxvg, as hygiene-005-1); register the origin before quarantining orphans', p_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections AS cc0 (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_quarantine_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'quarantine' ) ON CONFLICT (tenant_id, name) WHERE superseded_by = '' AND superseded_by_id IS NULL DO UPDATE SET content_type = EXCLUDED.content_type, owner_id = EXCLUDED.owner_id, embedding_model = EXCLUDED.embedding_model, model_version = EXCLUDED.model_version, dimension = EXCLUDED.dimension, superseded_by_id = CASE WHEN cc0.superseded_by = '' THEN NULL ELSE COALESCE(cc0.superseded_by_id, (SELECT s.collection_id FROM nexus.catalog_collections s WHERE s.tenant_id = cc0.tenant_id AND s.name = cc0.superseded_by), cc0.collection_id) END WHERE cc0.lifecycle_state = 'quarantine' OR NOT EXISTS (SELECT 1 FROM nexus.catalog_collections h WHERE h.tenant_id = cc0.tenant_id AND h.collection_id <> cc0.collection_id AND h.superseded_by = '' AND h.lifecycle_state <> 'quarantine' AND h.content_type = EXCLUDED.content_type AND h.owner_id = EXCLUDED.owner_id AND h.embedding_model = EXCLUDED.embedding_model AND h.model_version = EXCLUDED.model_version);
-- nexus-p2m1x.28 (linda 2026-11-25): the refresh above copies the ORIGIN's tuple onto a row that bears the sibling's name. For a quarantine row -- that is the designed heal and the row is outside catalog_collections_live_tuple_uq. A row of any other lifecycle that bears the name -- is inside the index, so the copy is skipped by the WHERE when another live row (the origin, as a rule) already holds that tuple, and -- the call refuses here by name: nothing moved, no second live holder, never a bare 23505. A non-quarantine row with no live twin of the tuple is refreshed as before. IF NOT FOUND THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: the row named % is not a quarantine collection and another live collection already holds the tuple of origin % that the quarantine sibling would copy onto it; nothing moved (the live tuple index allows one live holder of a tuple)', p_quarantine_collection, p_collection USING ERRCODE = 'invalid_parameter_value'; END IF;
-- two unique keys on nexus.chunks until P4.1 (the name primary key and P3.3b's id twin on (tenant_id, collection_id, chash, embedding_model)): the ON CONFLICT -- arbiter absorbs a race on itself only, so a racing writer's row trips the twin as a plain 23505. Retry once when the -- 23505 is that twin (a unique index whose partition root is nexus.chunks, on the id key's columns); the retry sees the committed row on the arbiter. Any other 23505, or a second one, is raised (linda 2026-11-22). FOR v_p35b_try IN 1 .. 2 LOOP BEGIN -- created_at CARRIED THROUGH (nexus-a6mon's second finding): the unbounded -- form omits it, so the default restamps every moved row to quarantine time -- and the collection's generation history is destroyed. -- RDR-225: embedding_model rides with the row; the arbiter is the four-column primary key. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, embedding_model, collection_id) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) || jsonb_strip_nulls(jsonb_build_object('origin_collection_id', (SELECT oc.collection_id FROM nexus.catalog_collections oc WHERE oc.tenant_id = p_tenant_id AND oc.name = p_collection))), c.created_at, c.embedding_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection) FROM nexus.chunks c JOIN _a6mon_victim v ON v.chash = c.chash WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) ON CONFLICT (tenant_id, collection, chash, embedding_model) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding_384 = EXCLUDED.embedding_384, embedding_768 = EXCLUDED.embedding_768, embedding_1024 = EXCLUDED.embedding_1024, metadata = EXCLUDED.metadata, created_at = EXCLUDED.created_at, collection_id = EXCLUDED.collection_id; EXIT; EXCEPTION WHEN unique_violation THEN GET STACKED DIAGNOSTICS v_p35b_con = CONSTRAINT_NAME; IF v_p35b_try = 2 OR NOT EXISTS ( SELECT 1 FROM pg_catalog.pg_class ic JOIN pg_catalog.pg_namespace ns ON ns.oid = ic.relnamespace JOIN pg_catalog.pg_index ix ON ix.indexrelid = ic.oid WHERE ns.nspname = 'nexus' AND ic.relname = v_p35b_con AND ix.indisunique AND coalesce(pg_catalog.pg_partition_root(ix.indrelid), ix.indrelid) = 'nexus.chunks'::regclass AND (SELECT pg_catalog.array_agg(a.attname::text ORDER BY a.attname) FROM pg_catalog.pg_attribute a WHERE a.attrelid = ix.indrelid AND a.attnum = ANY (ix.indkey)) = ARRAY['chash', 'collection_id', 'embedding_model', 'tenant_id']) THEN RAISE; END IF; END; END LOOP;
WITH del AS ( DELETE FROM nexus.chunks c USING _a6mon_victim v WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) AND c.chash = v.chash AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( p_tenant_id, p_collection, c.chash, c.last_written_at, NULL)) RETURNING c.tenant_id, c.collection, c.chash, c.embedding_model, left(c.chunk_text, 80) AS text_prefix ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(lim.chash, 'hex'), 'title', lim.title, 'text_prefix', lim.text_prefix)) AS s FROM (SELECT d.chash, d.text_prefix, (SELECT od.title FROM nexus.catalog_document_chunks oc JOIN nexus.catalog_documents od ON od.tenant_id = oc.tenant_id AND od.tumbler = oc.doc_id WHERE oc.tenant_id = d.tenant_id AND oc.chash = d.chash AND oc.embedding_model = d.embedding_model AND od.deleted_at IS NULL ORDER BY COALESCE((oc.collection_id = v_origin_id OR (oc.collection_id IS NULL AND oc.collection = p_collection AND p_collection <> '')), false) DESC, oc.doc_id LIMIT 1) AS title FROM del d LIMIT v_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
-- What is LEFT after this commit, so the caller has a terminator it does not -- have to invent from a stalling count. SELECT count(*) INTO v_remaining FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( p_tenant_id, p_collection, c.chash, c.last_written_at, NULL));
-- nexus-a6mon requirement 5: instrument it. The unbounded form logged only -- the edge's 499 -- no completion line, no timing, nothing between the cut -- and the eventual commit. INSERT INTO nexus.gc_audit (tenant_id, operation, collection, collection_id, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_quarantine_orphans_bounded', p_collection, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_collection), 'engine', false, v_moved, COALESCE( (SELECT jsonb_agg(elem->>'chash') FROM jsonb_array_elements(COALESCE(v_sample, '[]'::jsonb)) elem), '[]'::jsonb), jsonb_build_object( 'quarantine_collection', p_quarantine_collection, 'sample_limit', v_sample_limit, 'row_limit', v_row_limit, 'remaining_after', v_remaining, 'chashes_is_sample', true));
RETURN QUERY SELECT v_moved, v_sample, v_remaining; END; $function$;

