CREATE OR REPLACE FUNCTION nexus.reaper_quarantine_chunks(p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_row_limit integer, p_grace interval, p_floor_fraction double precision, p_floor_min_chunks integer, p_dry_run boolean) RETURNS TABLE(moved bigint, reapable_count bigint, total_count bigint, refused boolean, remaining bigint) LANGUAGE plpgsql AS $function$ DECLARE v_p35b_con text; -- the constraint of a unique_violation, for the retry on the id twin v_origin_id bigint; v_quar_id bigint; v_moved bigint; v_chashes jsonb; v_reapable bigint; v_total bigint; v_row_limit int; v_collision_count bigint; v_collision_sample text[]; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_collection; SELECT cc.collection_id INTO v_quar_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection; IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'reaper_quarantine_chunks: p_row_limit must be positive, got %', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF; IF p_floor_fraction IS NULL OR p_floor_fraction < 0 OR p_floor_fraction > 1 OR p_floor_min_chunks IS NULL OR p_floor_min_chunks < 0 THEN RAISE EXCEPTION 'reaper_quarantine_chunks: the floor must be a fraction in [0, 1] and a non-negative minimum, got % / %', p_floor_fraction, p_floor_min_chunks USING ERRCODE = 'invalid_parameter_value'; END IF; v_row_limit := LEAST(p_row_limit, 5000);
IF p_dry_run THEN SELECT count(*), count(*) FILTER (WHERE EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( p_tenant_id, p_collection, c.chash, c.last_written_at, p_grace))) INTO v_total, v_reapable FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')); RETURN QUERY SELECT 0::bigint, v_reapable, v_total, false, v_reapable; RETURN; END IF;
PERFORM set_config('lock_timeout', '2000', true); PERFORM set_config('statement_timeout', '25000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'reaper_quarantine_chunks: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer holds it; the reaper skips this collection until its next pass', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
-- Counted again UNDER the gate: the dry run's snapshot may be a pass old, and the floor must be judged -- on what is true while no manifest writer can move the ground. SELECT count(*), count(*) FILTER (WHERE EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( p_tenant_id, p_collection, c.chash, c.last_written_at, p_grace))) INTO v_total, v_reapable FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> ''));
IF v_reapable = 0 THEN RETURN QUERY SELECT 0::bigint, 0::bigint, v_total, false, 0::bigint; RETURN; END IF;
-- The floor on the move (see the header). Same shape as gc_expire_quarantine's: at least the minimum, and -- strictly more than the fraction. IF v_reapable >= p_floor_min_chunks AND v_reapable::float8 / v_total::float8 > p_floor_fraction THEN RETURN QUERY SELECT 0::bigint, v_reapable, v_total, true, v_reapable; RETURN; END IF;
-- THE VICTIM SET, chosen once and ordered for deterministic progress. CREATE TEMP TABLE IF NOT EXISTS _x9_victim(chash bytea PRIMARY KEY) ON COMMIT DROP; DELETE FROM _x9_victim; INSERT INTO _x9_victim(chash) SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( p_tenant_id, p_collection, c.chash, c.last_written_at, p_grace)) ORDER BY c.chash LIMIT v_row_limit;
-- Cross-dim collision guard (vectors-004's N7 guard): the unified PK cannot hold two different-dim rows. SELECT count(*), COALESCE(array_agg(encode(x.chash, 'hex') ORDER BY x.chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM nexus.chunks c JOIN _x9_victim v ON v.chash = c.chash JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND (e.collection_id = v_quar_id OR (e.collection_id IS NULL AND e.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND e.chash = c.chash WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) ) x WHERE x.src_dim IS DISTINCT FROM x.existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'reaper_quarantine_chunks: % cross-dim (tenant_id, collection, chash) collision(s) at quarantine target % for tenant=%, origin collection=%. Sample chashes: %. Refusing to overwrite.', v_collision_count, p_quarantine_collection, p_tenant_id, p_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- The sibling's attributes come from the ORIGIN's registered row, never from a name (RDR-204, -- hygiene-005-1). An unregistered origin is a fail-loud precondition. SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'reaper_quarantine_chunks: origin collection % is not registered for tenant % -- attributes for the quarantine sibling are copied from the origin row, never parsed from a name; register the origin before quarantining chunks', p_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections AS cc0 (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_quarantine_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'quarantine' ) ON CONFLICT (tenant_id, name) WHERE superseded_by = '' AND superseded_by_id IS NULL DO UPDATE SET content_type = EXCLUDED.content_type, owner_id = EXCLUDED.owner_id, embedding_model = EXCLUDED.embedding_model, model_version = EXCLUDED.model_version, dimension = EXCLUDED.dimension, superseded_by_id = CASE WHEN cc0.superseded_by = '' THEN NULL ELSE COALESCE(cc0.superseded_by_id, (SELECT s.collection_id FROM nexus.catalog_collections s WHERE s.tenant_id = cc0.tenant_id AND s.name = cc0.superseded_by), cc0.collection_id) END WHERE cc0.lifecycle_state = 'quarantine' OR NOT EXISTS (SELECT 1 FROM nexus.catalog_collections h WHERE h.tenant_id = cc0.tenant_id AND h.collection_id <> cc0.collection_id AND h.superseded_by = '' AND h.lifecycle_state <> 'quarantine' AND h.content_type = EXCLUDED.content_type AND h.owner_id = EXCLUDED.owner_id AND h.embedding_model = EXCLUDED.embedding_model AND h.model_version = EXCLUDED.model_version);
-- nexus-p2m1x.28 (linda 2026-11-25): the refresh above copies the ORIGIN's tuple onto a row that bears the sibling's name. For a quarantine row -- that is the designed heal and the row is outside catalog_collections_live_tuple_uq. A row of any other lifecycle that bears the name -- is inside the index, so the copy is skipped by the WHERE when another live row (the origin, as a rule) already holds that tuple, and -- the call refuses here by name: nothing moved, no second live holder, never a bare 23505. A non-quarantine row with no live twin of the tuple is refreshed as before. IF NOT FOUND THEN RAISE EXCEPTION 'reaper_quarantine_chunks: the row named % is not a quarantine collection and another live collection already holds the tuple of origin % that the quarantine sibling would copy onto it; nothing moved (the live tuple index allows one live holder of a tuple)', p_quarantine_collection, p_collection USING ERRCODE = 'invalid_parameter_value'; END IF;
-- two unique keys on nexus.chunks until P4.1 (the name primary key and P3.3b's id twin on (tenant_id, collection_id, chash, embedding_model)): the ON CONFLICT -- arbiter absorbs a race on itself only, so a racing writer's row trips the twin as a plain 23505. Retry once when the -- 23505 is that twin (a unique index whose partition root is nexus.chunks, on the id key's columns); the retry sees the committed row on the arbiter. Any other 23505, or a second one, is raised (linda 2026-11-22). FOR v_p35b_try IN 1 .. 2 LOOP BEGIN -- The move: DELETE with the predicate in its own WHERE, copy through RETURNING, one statement. A chunk a -- client refreshed after the victim set was chosen fails the recheck, is not deleted, and is not copied. WITH del AS ( DELETE FROM nexus.chunks c USING _x9_victim v WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) AND c.chash = v.chash AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( p_tenant_id, p_collection, c.chash, c.last_written_at, p_grace)) RETURNING c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, c.metadata, c.created_at, c.embedding_model ), copied AS ( -- RDR-225: the moved row keeps its embedding_model (the quarantine sibling is registered under the -- origin's model above); the arbiter is the four-column primary key. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, embedding_model, collection_id) SELECT p_tenant_id, p_quarantine_collection, d.chash, d.chunk_text, d.embedding_384, d.embedding_768, d.embedding_1024, COALESCE(d.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection, 'quarantined_by', 'engine-reaper', 'reaper_quarantined_at', p_quarantined_at) || jsonb_strip_nulls(jsonb_build_object('origin_collection_id', (SELECT oc.collection_id FROM nexus.catalog_collections oc WHERE oc.tenant_id = p_tenant_id AND oc.name = p_collection))), d.created_at, d.embedding_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection) FROM del d ON CONFLICT (tenant_id, collection, chash, embedding_model) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding_384 = EXCLUDED.embedding_384, embedding_768 = EXCLUDED.embedding_768, embedding_1024 = EXCLUDED.embedding_1024, metadata = EXCLUDED.metadata, created_at = EXCLUDED.created_at, collection_id = EXCLUDED.collection_id RETURNING 1 ) SELECT count(*), COALESCE(jsonb_agg(encode(d.chash, 'hex')), '[]'::jsonb) INTO v_moved, v_chashes FROM del d; EXIT; EXCEPTION WHEN unique_violation THEN GET STACKED DIAGNOSTICS v_p35b_con = CONSTRAINT_NAME; IF v_p35b_try = 2 OR NOT EXISTS ( SELECT 1 FROM pg_catalog.pg_class ic JOIN pg_catalog.pg_namespace ns ON ns.oid = ic.relnamespace JOIN pg_catalog.pg_index ix ON ix.indexrelid = ic.oid WHERE ns.nspname = 'nexus' AND ic.relname = v_p35b_con AND ix.indisunique AND coalesce(pg_catalog.pg_partition_root(ix.indrelid), ix.indrelid) = 'nexus.chunks'::regclass AND (SELECT pg_catalog.array_agg(a.attname::text ORDER BY a.attname) FROM pg_catalog.pg_attribute a WHERE a.attrelid = ix.indrelid AND a.attnum = ANY (ix.indkey)) = ARRAY['chash', 'collection_id', 'embedding_model', 'tenant_id']) THEN RAISE; END IF; END; END LOOP;
IF v_moved > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, collection_id, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'reaper_quarantine', p_collection, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_collection), 'engine-reaper', false, v_moved, v_chashes, jsonb_build_object( 'quarantine_collection', p_quarantine_collection, 'row_limit', v_row_limit, 'grace', COALESCE(p_grace::text, 'default'), 'floor_fraction', p_floor_fraction, 'floor_min_chunks', p_floor_min_chunks, 'reapable_before', v_reapable, 'total_before', v_total, 'remaining_after', GREATEST(v_reapable - v_moved, 0))); END IF;
RETURN QUERY SELECT v_moved, v_reapable, v_total, false, GREATEST(v_reapable - v_moved, 0); END; $function$;

