-- Cross-dim collision guard (vectors-004's N7 guard): the unified PK cannot hold two different-dim rows. SELECT count(*), COALESCE(array_agg(encode(x.chash, 'hex') ORDER BY x.chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM nexus.chunks c JOIN _x9_victim v ON v.chash = c.chash JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND (e.collection_id = v_quar_id OR (e.collection_id IS NULL AND e.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND e.chash = c.chash WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_origin_id OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) ) x WHERE x.src_dim IS DISTINCT FROM x.existing_dim;
