CREATE OR REPLACE FUNCTION nexus.gc_restore_rereferenced_bounded(dim integer, p_tenant_id text, p_quarantine_collection text, p_origin_collection text, p_row_limit integer) RETURNS TABLE(restored bigint, remaining bigint) LANGUAGE plpgsql AS $function$ DECLARE v_p28_holder text; -- nexus-p2m1x.28: the live holder of the tuple a first-ever origin would take v_origin_id bigint; v_quar_id bigint; -- RDR-229 P3.7 (vectors-083): read once, at the top of the call; from gate 3 a quarantined chunk is the origin's by the origin's id v_latched boolean := EXISTS (SELECT 1 FROM nexus.rdr229_gate_latch WHERE gate = 'gate3'); v_chashes bytea[]; v_restored bigint := 0; v_remaining bigint := 0; v_row_limit int; v_row_count bigint := 0; v_collision_count bigint; v_collision_sample text[]; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection; SELECT cc.collection_id INTO v_quar_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection; IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_restore_rereferenced_bounded: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- A non-positive bound is a caller error, not "unbounded". The whole -- point of this function is the bound; silently removing it would hand -- back the exact unbounded transaction this exists to prevent (mirrors -- catalog-037's identical guard). IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'gc_restore_rereferenced_bounded: p_row_limit must be positive, got %. Use nexus.gc_restore_rereferenced for the unbounded restore.', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
v_row_limit := LEAST(p_row_limit, 100000);
-- THE VICTIM SET, chosen ONCE and ordered for deterministic progress -- across calls (nexus-a6mon's requirement, mirrored here). Unlike -- gc_quarantine_orphans's unbounded form, gc_restore_rereferenced -- ALREADY keys its copy-INSERT and DELETE off one array selected once -- (catalog-039-1's own shape) -- the only change needed to bound it is -- this ORDER BY chash LIMIT on the initial selection. SELECT array_agg(x.chash ORDER BY x.chash) INTO v_chashes FROM ( SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND CASE WHEN v_latched THEN c.metadata->'origin_collection_id' = to_jsonb(v_origin_id) ELSE COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection END AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> '')) AND m.chash = c.chash ) ORDER BY c.chash LIMIT v_row_limit ) x;
IF v_chashes IS NULL THEN RETURN QUERY SELECT 0::bigint, 0::bigint; RETURN; END IF;
-- N7-STYLE cross-dim collision guard (identical to catalog-039-1's, -- scoped to this batch's v_chashes): detect, BEFORE any row moves, any -- restore candidate whose chash already exists at p_origin_collection -- under a DIFFERENT populated embedding_<dim> column than the -- candidate's own. WITH candidate AS ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND c.chash = ANY(v_chashes) ), collision AS ( SELECT cand.chash, cand.src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM candidate cand JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND (e.collection_id = v_origin_id OR (e.collection_id IS NULL AND e.collection = p_origin_collection AND p_origin_collection <> '')) AND e.chash = cand.chash ) SELECT count(*), COALESCE(array_agg(encode(chash, 'hex') ORDER BY chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM collision WHERE src_dim IS DISTINCT FROM existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_restore_rereferenced_bounded: % cross-dim (tenant_id, collection, chash) collision(s) at restore target % for tenant=%, quarantine collection=% -- the unified PK cannot hold two different-dim rows for the same chash (mirrors vectors-004''s N7 guard, T2 22454). Sample chashes: %. Refusing to overwrite; verify the origin-collection naming keeps distinct dims/collections separated before retrying.', v_collision_count, p_origin_collection, p_tenant_id, p_quarantine_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
