INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_origin_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'live' ) ON CONFLICT (tenant_id, name) WHERE superseded_by = '' AND superseded_by_id IS NULL DO NOTHING;
-- The origin's id is read again now that it is registered: a first-ever origin had none when the body began, and a -- racing registration (the DO NOTHING above) may have committed one since. SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection;
-- created_at CARRIED THROUGH (nexus-e8h5x, mirroring catalog-037's fix -- for the opposite direction): the unbounded gc_restore_rereferenced's -- INSERT omits it, so the default restamps every restored row to -- restore time and the chunk's generation history through the -- quarantine round trip is lost. -- RDR-225: embedding_model rides with the row (the chunk's own model, never the origin collection's: an -- origin registered under another model refuses the row at the composite foreign key instead of filing a -- vector under a model that did not embed it); the arbiter is the four-column primary key. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, embedding_model, collection_id) SELECT p_tenant_id, p_origin_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, -- RDR-236 (nexus-6pfgb.40): the restored row holds only the CHUNK keys of the key table. The four quarantine keys -- (quarantined_at, origin_collection, quarantined_by, reaper_quarantined_at) are the physical row's, written by the -- engine's two quarantine moves, and every other key is a document or position key whose home is the catalog. -- Both are derived from the columns, so the Phase 4 equalities hold by construction. jsonb_build_object('chunk_text_hash', encode(c.chash, 'hex'), 'embedding_model', c.embedding_model), c.created_at, c.embedding_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection) FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND c.chash = ANY(v_chashes) -- target-less: absorbs the name key and the id twin alike (RDR-229 P3.5b, two unique keys until P4.1) ON CONFLICT DO NOTHING;
-- nexus-brxnp fix round: rows genuinely inserted vs. rows skipped -- because the origin already had a live row for that chash (the DO -- NOTHING conflict) -- recorded below as `already_live` so a -- production investigation can tell the two apart without re-deriving -- it from chunk timestamps by hand (T2 nexus/debug-u6d93-brxnp). GET DIAGNOSTICS v_row_count = ROW_COUNT;
DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND c.chash = ANY(v_chashes);
v_restored := array_length(v_chashes, 1);
